 document.querySelectorAll('[data-home-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.homeAction;if(a==='games')document.querySelector('#newGamesShelf')?.scrollIntoView({behavior:'smooth'});else if(a==='lodge')document.querySelector('#gameLodgeShelf')?.scrollIntoView({behavior:'smooth'});else openHomePanel(a)});
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{const a=el.dataset.action;try{
   if(a==='join')return joinRoom();if(a==='avatarBack'){session.avatarPickStage='character';render();return}if(a==='avatarDone'){session.avatarPickStage='outfit';return}if(a==='addBot'){const difficulty=document.querySelector('#botDifficulty')?.value||'medium',avatar=document.querySelector('#botCharacter')?.value||'auto',variantRaw=document.querySelector('#botVariant')?.value,variant=variantRaw==null||variantRaw===''?null:Number(variantRaw);await api('addBot',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,difficulty,avatar:avatar==='auto'?null:avatar,variant});return;}if(a==='toggleGameSwitcher'){session.gameSwitcherOpen=!session.gameSwitcherOpen;render();return}if(a==='retryConnect'){session.connectionIssue=false;session.state=null;connect();render();return}if(a==='copy'){await navigator.clipboard.writeText(inviteLink());el.textContent='Copied!';setTimeout(render,900);return}if(a==='shareInvite'){const title=session.state?.gameName||'Black Family Game Night',url=inviteLink();if(navigator.share){await navigator.share({title,text:`Join my ${title} game`,url})}else{await navigator.clipboard.writeText(url);el.textContent='Link Copied!';setTimeout(render,900)}return}if(a==='home')return goHome();if(a==='toggleSchedule'){session.scheduleOpen=!session.scheduleOpen;render();return}if(a==='dismissCeremony'){session.ceremonyDismissed=true;render();return}
   const b={roomId:session.roomId,playerToken:session.playerToken};
   if(a==='start')await api('start',{...b,hostToken:session.hostToken});
   if(a==='ready'){const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('ready',{...b,ready:!me.ready})}
   if(a==='saveProfile'){const me=session.state.players.find(p=>p.id===session.state.viewerId),name=document.querySelector('#profileName')?.value.trim()||me.name;session.name=name;localStorage.setItem('gn_name',name);await api('profile',{...b,name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:me.color})}
      if(a==='saveSettings'){const payload={...b,hostToken:session.hostToken};document.querySelectorAll('[data-setting]').forEach(el=>{payload[el.dataset.setting]=el.type==='checkbox'?el.checked:el.value});await api('settings',payload)}
   if(a==='confirmBid'){if(session.selectedBid==null)return;await api('bid',{...b,bid:session.selectedBid});session.selectedBid=null}
   if(a==='confirmCard'){if(!session.selectedCard)return;await api('play',{...b,cardId:session.selectedCard});session.selectedCard=null}
   if(a==='continue')await api('continue',b);
   if(a==='chat'){const input=document.querySelector('#chatInput'),text=input?.value.trim();if(text){await api('chat',{...b,text});input.value='';const fresh=await fetchState(session.roomId,session.playerToken);setRoomState(fresh);render()}}
 }catch(e){setError(e)}});
 const seat=document.querySelector('#seatSelect');if(seat)seat.onchange=async()=>{if(seat.value==='')return;try{await api('seat',{roomId:session.roomId,playerToken:session.playerToken,seat:Number(seat.value)})}catch(e){setError(e)}};
 document.querySelectorAll('[data-avatar]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId),target=el.dataset.avatar;const variant=target==='john'?(me.avatar==='john'?Math.min(Number(me.variant||1),johnLooks.length+familyPackStyles.length-1):1):(familyAvatarIds.has(target)?(me.avatar===target?Math.min(Number(me.variant||0),avatarStyles.length+familyPackStyles.length-1):0):(me.avatar===target?Number(me.variant||0)%avatarStyles.length:0));me.avatar=target;me.variant=variant;session.avatarPickStage='outfit';render();await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:target,variant,outfitVariant:me.outfitVariant,color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-color]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:me.avatar,variant:me.variant,outfitVariant:me.outfitVariant,color:el.dataset.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-style]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:me.avatar,variant:Number(el.dataset.style),outfitVariant:me.outfitVariant,color:me.color})}catch(e){setError(e)}});
 document.querySelectorAll('[data-outfit]').forEach(el=>el.onclick=async()=>{try{const me=session.state.players.find(p=>p.id===session.state.viewerId);await api('profile',{roomId:session.roomId,playerToken:session.playerToken,name:me.name,avatar:me.avatar,variant:me.variant,outfitVariant:Number(el.dataset.outfit),color:me.color})}catch(e){setError(e)}});
 const botCharacter=document.querySelector('#botCharacter'),botVariant=document.querySelector('#botVariant');if(botCharacter&&botVariant)botCharacter.onchange=()=>{botVariant.innerHTML=botVariantOptions(botCharacter.value,0);botVariant.disabled=botCharacter.value==='auto'};
 document.querySelectorAll('[data-bot-character]').forEach(sel=>sel.onchange=()=>{const target=document.querySelector(`[data-bot-variant="${sel.dataset.botCharacter}"]`);if(target)target.innerHTML=botVariantOptions(sel.value,0)});
 document.querySelectorAll('[data-update-bot]').forEach(el=>el.onclick=async()=>{try{const id=el.dataset.updateBot,avatar=document.querySelector(`[data-bot-character="${id}"]`)?.value,variant=Number(document.querySelector(`[data-bot-variant="${id}"]`)?.value||0),difficulty=document.querySelector(`[data-bot-difficulty="${id}"]`)?.value;await api('updateBot',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,targetId:id,avatar,variant,difficulty});}catch(e){setError(e)}});
 document.querySelectorAll('[data-remove-player]').forEach(el=>el.onclick=async()=>{try{await api('removePlayer',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,targetId:el.dataset.removePlayer})}catch(e){setError(e)}});
 document.querySelectorAll('[data-bid]').forEach(el=>el.onclick=()=>{session.selectedBid=session.state?.gameType===GAME.SMEAR?el.dataset.bid:Number(el.dataset.bid);render()});
 document.querySelectorAll('[data-card]').forEach(el=>el.onclick=()=>{session.selectedCard=el.dataset.card;render()});
