 document.querySelectorAll('[data-extra-card-clear]').forEach(el=>el.onclick=()=>{session.selectedExtraCard=null;render()});
 document.querySelectorAll('[data-extra-action]').forEach(el=>el.onclick=async()=>{try{const e=session.state?.game?.extra,a=e?.actions?.[Number(el.dataset.extraAction)];if(!a)return;await api('gameAction',{roomId:session.roomId,playerToken:session.playerToken,action:a.action,args:a.args||{}});session.selectedExtraCard=null}catch(err){setError(err)}});
 document.querySelectorAll('[data-switch-game]').forEach(el=>el.onclick=async()=>{try{await api('switchGame',{roomId:session.roomId,playerToken:session.playerToken,hostToken:session.hostToken,gameType:el.dataset.switchGame});session.gameSwitcherOpen=false}catch(err){setError(err)}});
 document.querySelectorAll('[data-trail-zoom]').forEach(el=>el.onclick=()=>{const a=el.dataset.trailZoom;if(a==='reset')session.trailZoom=1;else if(a==='in')session.trailZoom=Math.min(2.2,(Number(session.trailZoom)||1)+.25);else session.trailZoom=Math.max(1,(Number(session.trailZoom)||1)-.25);render()});
 document.querySelectorAll('[data-trail-card-select]').forEach(el=>el.onclick=()=>{session.trailCardActive=true;session.selectedTrailPawn=null;render()});
 document.querySelectorAll('[data-trail-pawn]:not([data-extra-action])').forEach(el=>el.onclick=()=>{if(!session.trailCardActive)return;session.selectedTrailPawn=el.dataset.trailPawn;render()});
 document.querySelectorAll('[data-trail-clear-pawn]').forEach(el=>el.onclick=()=>{session.selectedTrailPawn=null;render()});
